    function updateViewerImage() {
      const product = products.find(item => item.id === viewerProductId);
      if (!product) return;
      const images = getProductImages(product);
      if (!images.length) return;
      viewerImageIndex = (viewerImageIndex + images.length) % images.length;
      const image = document.getElementById('product-viewer-image');
      image.src = images[viewerImageIndex];
      image.alt = product.name || 'Product image';
      image.style.transform = `scale(${viewerScale})`;
      document.getElementById('product-viewer-title').textContent = product.name || 'Product';
      document.getElementById('product-viewer-count').textContent = `${viewerImageIndex + 1} / ${images.length}`;
      document.getElementById('product-viewer-prev').disabled = images.length < 2;
      document.getElementById('product-viewer-next').disabled = images.length < 2;
      document.getElementById('product-viewer-zoom').textContent = viewerScale > 1 ? '−' : '+';
    }

    function openProductViewer(productId, index = 0) {
      const product = products.find(item => item.id === productId);
      if (!product) return;
      viewerProductId = productId;
      viewerImageIndex = index;
      viewerScale = 1;
      updateViewerImage();
      const modal = document.getElementById('product-viewer');
      modal.classList.remove('hidden');
      modal.setAttribute('aria-hidden', 'false');
      document.body.classList.add('product-viewer-open');
    }

    function closeProductViewer() {
      const modal = document.getElementById('product-viewer');
      if (!modal) return;
      modal.classList.add('hidden');
      modal.setAttribute('aria-hidden', 'true');
      document.body.classList.remove('product-viewer-open');
      viewerProductId = null;
      viewerScale = 1;
    }

    function moveViewerImage(direction) {
      const product = products.find(item => item.id === viewerProductId);
      if (!product) return;
      viewerImageIndex += direction;
      viewerScale = 1;
      updateViewerImage();
    }

    function toggleViewerZoom() {
      viewerScale = viewerScale > 1 ? 1 : 2;
      updateViewerImage();
    }

    function viewerDistance(touches) {
      const dx = touches[0].clientX - touches[1].clientX;
      const dy = touches[0].clientY - touches[1].clientY;
      return Math.hypot(dx, dy);
    }

    function normalizeImageUrl(rawUrl) {
      const u = (rawUrl || '').trim();
      if (!u) return '';
      const driveFileMatch = u.match(/drive\.google\.com\/file\/d\/([^/]+)/i);
      if (driveFileMatch) return 'https://lh3.googleusercontent.com/d/' + driveFileMatch[1];
      const driveOpenMatch = u.match(/drive\.google\.com\/(?:open|uc)\?(?:[^#]*&)?id=([^&#]+)/i);
      if (driveOpenMatch) return 'https://lh3.googleusercontent.com/d/' + driveOpenMatch[1];
      if (/dropbox\.com/i.test(u) && u.includes('dl=0')) return u.replace('dl=0', 'raw=1');
      return u;
    }

    function handleImgError(imgEl) {
      if (!imgEl || imgEl.dataset.fallbackApplied) return;
      imgEl.dataset.fallbackApplied = '1';
      imgEl.src = IMG_SUITCASE;
    }

    function compressImageFile(file, maxDim = 900, quality = 0.84) {
      return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onload = (ev) => {
          const dataUrl = ev.target.result;
          const img = new Image();
          img.onload = () => {
            try {
              let w = img.naturalWidth || img.width;
              let h = img.naturalHeight || img.height;
              if (!w || !h) { resolve(dataUrl); return; }
              if (w > maxDim || h > maxDim) {
                if (w >= h) { h = Math.round(h * (maxDim / w)); w = maxDim; }
                else { w = Math.round(w * (maxDim / h)); h = maxDim; }
              }
              const canvas = document.createElement('canvas');
              canvas.width = w;
              canvas.height = h;
              const ctx = canvas.getContext('2d');
              ctx.drawImage(img, 0, 0, w, h);
              const outType = (file.type === 'image/png' || file.type === 'image/webp') ? 'image/png' : 'image/jpeg';
              resolve(canvas.toDataURL(outType, quality));
            } catch (err) {
              resolve(dataUrl);
            }
          };
          img.onerror = () => resolve(dataUrl);
          img.src = dataUrl;
        };
        reader.onerror = () => resolve('');
        reader.readAsDataURL(file);
      });
    }

    function getProductImages(p) {
      if (p && Array.isArray(p.images) && p.images.length > 0) return p.images;
      if (p && p.image) return [p.image];
      return [IMG_SUITCASE];
    }

    function renderOwnerImageGallery() {
      const preview = document.getElementById('owner-img-preview');
      const gallery = document.getElementById('owner-img-gallery-preview');
      if (preview) {
        preview.src = uploadedOwnerImages[0] || uploadedOwnerImage || IMG_SUITCASE;
      }
      if (!gallery) return;
      if (!uploadedOwnerImages.length) {
        gallery.innerHTML = '<span class="text-[11px] text-gray-500">No images added yet (default placeholder will be used if empty).</span>';
        return;
      }
      gallery.innerHTML = uploadedOwnerImages.map((src, idx) => `
        <div class="relative group w-14 h-14 rounded-lg overflow-hidden border ${idx === 0 ? 'border-red-600 ring-2 ring-red-400/50' : 'border-gray-300'} bg-gray-100 shrink-0">
          <img src="${src}" alt="Image ${idx + 1}" referrerpolicy="no-referrer" onerror="handleImgError(this)" class="w-full h-full object-cover" />
          ${idx === 0 ? '<span class="absolute bottom-0 left-0 right-0 bg-red-600/90 text-white text-[8px] font-black text-center leading-tight py-0.5">MAIN</span>' : ''}
          <button type="button" data-remove-owner-img="${idx}" class="absolute top-0.5 right-0.5 w-4 h-4 rounded-full bg-black/75 text-white text-[10px] font-black flex items-center justify-center hover:bg-red-600">&times;</button>
        </div>
      `).join('');
    }

    // --- ACCESSIBILITY & DEVELOPER UNDO STATE ---
    const DEFAULT_A11Y = {
      theme: 'dark', // 'light' (reddish-white) | 'dark' (reddish-maroon)
      highContrast: false,
      reduceMotion: false,
      largeText: false
    };
    let a11yState = { ...DEFAULT_A11Y };
    let devHistory = [];
    let devDebounceTimer = null;
    let devPendingSnapshot = null;

    function cloneStateSnapshot() {
      return {
        config: JSON.parse(JSON.stringify(config)),
        products: JSON.parse(JSON.stringify(products))
      };
    }

    function updateDevUndoUI() {}

    function pushDevSnapshot(snap) {
      devHistory.push(snap || cloneStateSnapshot());
      if (devHistory.length > 40) devHistory.shift();
      updateDevUndoUI();
      document.getElementById('dev-undo-btn').addEventListener('click', undoDevChange);
    }

    function pushDevSnapshotDebounced() {
      if (!devPendingSnapshot) {
        devPendingSnapshot = cloneStateSnapshot();
      }
      clearTimeout(devDebounceTimer);
      devDebounceTimer = setTimeout(() => {
        if (devPendingSnapshot) {
          pushDevSnapshot(devPendingSnapshot);
          devPendingSnapshot = null;
        }
      }, 450);
    }

    function undoDevChange() {
      if (devPendingSnapshot) {
        clearTimeout(devDebounceTimer);
        pushDevSnapshot(devPendingSnapshot);
        devPendingSnapshot = null;
      }
      if (!devHistory.length) {
        showToast('Nothing to undo');
        return;
      }
      const prev = devHistory.pop();
      config = prev.config;
      products = prev.products;
      saveConfig();
      saveProducts();
      applyConfigToDOM();
      renderBrands();
      renderCategories();
      renderCatalog();
      renderOwnerImageGallery();
      renderOwnerInventory();
      updateDevUndoUI();
      showToast('Undid last developer change');
    }

    function loadA11yState() {
      try {
        const saved = localStorage.getItem('srinivasa_a11y_v1');
        if (saved) a11yState = { ...DEFAULT_A11Y, ...JSON.parse(saved) };
      } catch (e) {
        a11yState = { ...DEFAULT_A11Y };
      }
    }

    function saveA11yState() {
      try { localStorage.setItem('srinivasa_a11y_v1', JSON.stringify(a11yState)); } catch (e) {}
    }

    function applyA11yToDOM() {
      const root = document.documentElement;
      const isDark = a11yState.theme !== 'light';
      root.setAttribute('data-theme', isDark ? 'dark' : 'light');
      root.setAttribute('data-high-contrast', a11yState.highContrast ? 'true' : 'false');
      root.setAttribute('data-reduce-motion', a11yState.reduceMotion ? 'true' : 'false');
      root.setAttribute('data-large-text', a11yState.largeText ? 'true' : 'false');

      const lightBtn = document.getElementById('theme-light-btn');
      const darkBtn = document.getElementById('theme-dark-btn');
      if (lightBtn && darkBtn) {
        lightBtn.setAttribute('aria-checked', isDark ? 'false' : 'true');
        darkBtn.setAttribute('aria-checked', isDark ? 'true' : 'false');
        lightBtn.classList.toggle('a11y-theme-active', !isDark);
        darkBtn.classList.toggle('a11y-theme-active', isDark);
      }
      const contrastBadge = document.getElementById('a11y-contrast-badge');
      const contrastBtn = document.getElementById('a11y-contrast-btn');
      if (contrastBtn && contrastBadge) {
        contrastBtn.setAttribute('aria-pressed', a11yState.highContrast ? 'true' : 'false');
        contrastBadge.textContent = a11yState.highContrast ? 'ON' : 'OFF';
      }
      const motionBadge = document.getElementById('a11y-motion-badge');
      const motionBtn = document.getElementById('a11y-motion-btn');
      if (motionBtn && motionBadge) {
        motionBtn.setAttribute('aria-pressed', a11yState.reduceMotion ? 'true' : 'false');
        motionBadge.textContent = a11yState.reduceMotion ? 'ON' : 'OFF';
      }
      const textBadge = document.getElementById('a11y-textsize-badge');
      const textBtn = document.getElementById('a11y-textsize-btn');
      if (textBtn && textBadge) {
        textBtn.setAttribute('aria-pressed', a11yState.largeText ? 'true' : 'false');
        textBadge.textContent = a11yState.largeText ? 'ON' : 'OFF';
      }
    }

    // --- STORAGE HELPERS ---
    async function loadState() {
      // Local data is a temporary fallback for first-time setup/offline access.
      try {
        const savedProds = localStorage.getItem('srinivasa_products_v1');
        const savedOffers = localStorage.getItem('srinivasa_offers_v1');
        const savedConf = localStorage.getItem('srinivasa_config_v1');
        const savedCart = localStorage.getItem('srinivasa_cart_v1');
        products = savedProds ? JSON.parse(savedProds) : [...DEFAULT_PRODUCTS];
        offers = savedOffers ? JSON.parse(savedOffers) : [...DEFAULT_OFFERS];
        config = savedConf ? { ...DEFAULT_CONFIG, ...JSON.parse(savedConf) } : { ...DEFAULT_CONFIG };
        cart = savedCart ? JSON.parse(savedCart) : [];
      } catch (e) {
        products = [...DEFAULT_PRODUCTS]; offers = [...DEFAULT_OFFERS];
        config = { ...DEFAULT_CONFIG }; cart = [];
      }
      if (supabaseReady) {
        try {
          await Promise.race([
            loadCloudState(),
            new Promise(resolve => setTimeout(() => resolve(false), 4500))
          ]);
        } catch (cloudLoadError) {
          console.warn('Cloud load failed; using the local storefront cache.', cloudLoadError);
          setCloudMessage('Could not reach cloud. Showing saved catalogue on this device.', true);
        }
      }
    }

    function saveOffers() { scheduleCloudSave(); }
    function saveProducts() { scheduleCloudSave(); }
    function saveConfig() { scheduleCloudSave(); }
    function saveCart() {
      try { localStorage.setItem('srinivasa_cart_v1', JSON.stringify(cart)); } catch (e) {}
    }

    // --- TOAST ---
    let toastTimer = null;
    function showToast(msg) {
      const el = document.getElementById('toast');
      document.getElementById('toast-msg').textContent = msg;
      el.classList.remove('hidden');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => el.classList.add('hidden'), 2600);
    }

    // --- APPLY DEVELOPER CONFIG LIVE ---
