          pEl.innerHTML = (config.phones || []).map((ph, i) => `
            <div class="flex items-center justify-between bg-gray-800 px-2 py-1 rounded">
              <span class="truncate">${ph}</span>
              <button type="button" data-del-phone="${i}" class="text-red-400 hover:text-red-300 font-bold ml-2">&times;</button>
            </div>
          `).join('');
