        const wEl = document.getElementById('dev-wa-list');
        if (wEl) {
          wEl.innerHTML = (config.whatsapps || []).map((w, i) => `
            <div class="flex items-center justify-between bg-gray-800 px-2 py-1 rounded">
              <span class="truncate">${w}</span>
              <button type="button" data-del-wa="${i}" class="text-red-400 hover:text-red-300 font-bold ml-2">&times;</button>
            </div>
          `).join('');
        }
        const sEl = document.getElementById('dev-socials-list');
